css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .recuerda{border: 2px solid var(--bosque); border-radius: 10px; padding: 6px 12px; margin-bottom: 8px;}
.mz .recuerda-titulo{font-size: 13px; font-weight: 700; margin-bottom: 3px; display: flex; align-items: center; gap: 6px;}
.mz .recuerda-idea{font-size: 12.5px; margin-bottom: 2px; line-height: 1.28;}
.mz .recuerda-idea strong{font-weight: 700;}
.mz .moneda-svg{width: 46px; height: 46px; display: inline-block; vertical-align: middle;}
.mz .billete-svg{width: 74px; height: 42px; display: inline-block; vertical-align: middle;}
.mz .mini-moneda-svg{width: 32px; height: 32px; display: inline-block; vertical-align: middle;}
.mz .mini-billete-svg{width: 50px; height: 28px; display: inline-block; vertical-align: middle;}
.mz .escribir-fila{display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; justify-items: center;}
.mz .escribir-caja{display: flex; flex-direction: column; align-items: center; gap: 5px;}
.mz .escribir-hueco{width: 62px; border: 1.5px solid var(--bosque); border-radius: 4px; height: 24px;}
.mz .contar-linea{display: flex; align-items: center; gap: 5px; flex-wrap: wrap; border: 1.5px solid var(--bosque); border-radius: 9px; padding: 5px 9px; margin-bottom: 6px;}
.mz .contar-linea .total{display: inline-block; min-width: 52px; border: 1.6px solid var(--bosque); border-radius: 5px; height: 26px; margin-left: 4px;}
.mz .contar-linea .eq{font-size: 13px; font-weight: 700; margin-left: auto;}
.mz .comp-grid{display: grid; grid-template-columns: 1fr 1fr; gap: 10px;}
.mz .comp-celda{display: flex; align-items: center; justify-content: center; gap: 4px; flex-wrap: wrap; border: 1.6px solid var(--bosque); border-radius: 10px; padding: 7px;}
.mz .problema{border: 1.6px solid var(--bosque); border-radius: 9px; padding: 7px 11px; margin-bottom: 8px; font-size: 13.5px; line-height: 1.35;}
.mz .op-line{display: flex; align-items: center; gap: 8px; margin-top: 6px; font-family: sans-serif; font-weight: 700; font-size: 13px; flex-wrap: wrap;}
.mz .op-line .sol{flex: 1; min-width: 100px; border-bottom: 1.4px solid var(--bosque); height: 16px;}
.mz .caja{width: 44px; height: 26px; border: 1.6px solid var(--bosque); border-radius: 6px; display: inline-block; vertical-align: middle;}
.mz .pill{border: 1.5px solid var(--bosque); border-radius: 999px; padding: 2px 12px; font-size: 12px; font-weight: 700; font-family: sans-serif; white-space: nowrap;}
.mz .llega-fila{display: flex; align-items: center; gap: 10px; border: 1.5px solid var(--bosque); border-radius: 9px; padding: 6px 11px; margin-bottom: 6px; flex-wrap: wrap;}
.mz .llega-obj{font-size: 13px; font-weight: 700;}
.mz .llega-tengo{font-size: 13px; font-weight: 700;}
.mz .llega-ops{display: flex; gap: 7px; margin-left: auto;}
.mz .falta-grid{display: grid; grid-template-columns: 1fr 1fr; gap: 7px 22px;}
.mz .falta-fila{display: flex; align-items: center; gap: 5px; border: 1.5px solid var(--bosque); border-radius: 8px; padding: 6px 10px; font-size: 12.5px; font-weight: 700; flex-wrap: wrap;}
.mz .dibujar-fila{display: flex; align-items: center; gap: 10px; border: 1.5px solid var(--bosque); border-radius: 9px; padding: 6px 10px; margin-bottom: 6px;}
.mz .dibujar-txt{font-size: 13.5px; font-weight: 700;}
.mz .dibujar-zona{flex: 1; height: 46px; border: 1.4px dashed #000; border-radius: 6px; margin-left: 6px;}
.mz .txt-flex{flex: 1 1 auto; min-width: 0;}
.mz .recuerda-idea{line-height: 1.725 !important;}
